import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function root(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extension-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}
function write(dir, name, value = 'x', mode = 0o644) {
  const target = path.join(dir, ...name.split('/'));
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, value); fs.chmodSync(target, mode);
}
function run(...args) { return spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' }); }
function invalid(result) {
  assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
}

test('manifest ordering, exact bytes, empty selection, and inputs remain unchanged', t => {
  const dir = root(t); const names = ['z', ' a', 'é', 'a\nb', 'a\tb'];
  for (const name of names) write(dir, name, Buffer.from([0, 255, name.length]));
  const input = [...names].reverse(); const before = [...input];
  const manifest = createManifest(dir, input);
  assert.deepEqual(input, before);
  assert.deepEqual(manifest.files.map(x => x.path), [...names].sort((a, b) => a < b ? -1 : a > b ? 1 : 0));
  assert.deepEqual(createManifest(dir, []), { version: 1, files: [] });
  const copy = structuredClone(manifest); assert.deepEqual(verifyManifest(dir, manifest), { ok: true, unchanged: manifest.files.map(x => x.path), changed: [], missing: [], unsafe: [] });
  assert.deepEqual(manifest, copy);
});

test('verifier validates complete manifests before checking files', t => {
  const dir = root(t); write(dir, 'a'); const good = createManifest(dir, ['a']).files[0];
  const bads = [null, [], {}, { version: 1 }, { version: 1, files: {} }, { version: 1, files: [null] },
    { version: 1, files: [{ ...good, path: 'a' }, { ...good, path: 'a' }] },
    ...['42', -1, 1.2, Number.MAX_SAFE_INTEGER + 1].map(size => ({ version: 1, files: [{ ...good, size }] })),
    ...[-1, 512, 1.1].map(mode => ({ version: 1, files: [{ ...good, mode }] })),
    ...['A'.repeat(64), 'a'.repeat(63), 3].map(sha256 => ({ version: 1, files: [{ ...good, sha256 }] })),
    ...['', '/a', 'a//b', './a', '../a', 'a/../b', 'a\\b', 'a\0b'].map(path => ({ version: 1, files: [{ ...good, path }] }))];
  for (const manifest of bads) assert.throws(() => verifyManifest(dir, manifest));
  assert.throws(() => createManifest(dir, ['a', 'a']));
  assert.throws(() => createManifest(dir, 'a'));
});

test('all drift buckets and ordered content/mode reasons', t => {
  const dir = root(t);
  for (const name of ['same', 'both', 'mode', 'size', 'gone', 'nest/gone', 'link', 'file/child', 'final']) write(dir, name, name);
  const manifest = createManifest(dir, ['same', 'both', 'mode', 'size', 'gone', 'nest/gone', 'link', 'file/child', 'final']);
  write(dir, 'both', 'new', 0o600); fs.chmodSync(path.join(dir, 'mode'), 0o600);
  fs.unlinkSync(path.join(dir, 'gone')); fs.rmSync(path.join(dir, 'nest'), { recursive: true });
  fs.unlinkSync(path.join(dir, 'link')); fs.symlinkSync(path.join(dir, 'same'), path.join(dir, 'link'));
  fs.rmSync(path.join(dir, 'file'), { recursive: true }); write(dir, 'file', 'not dir');
  fs.unlinkSync(path.join(dir, 'final')); fs.mkdirSync(path.join(dir, 'final'));
  const sizeEntry = manifest.files.find(x => x.path === 'size'); sizeEntry.size = 0;
  const report = verifyManifest(dir, manifest);
  assert.deepEqual(report, { ok: false, unchanged: ['same'], changed: [
    { path: 'both', reasons: ['content', 'mode'] }, { path: 'mode', reasons: ['mode'] }, { path: 'size', reasons: ['content'] },
  ], missing: ['gone', 'nest/gone'], unsafe: ['file/child', 'final', 'link'] });
});

test('roots and symlinks are rejected', t => {
  const dir = root(t); write(dir, 'a'); const manifest = createManifest(dir, ['a']);
  const link = `${dir}-link`; fs.symlinkSync(dir, link); t.after(() => fs.rmSync(link, { force: true }));
