import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-retained-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}
function write(dir, name, content = name) {
  const target = path.join(dir, ...name.split('/'));
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content);
}
function run(...args) { return spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' }); }
function invalid(result) {
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.notEqual(result.stderr, '');
}

test('manifest validation rejects hashes with line terminators', t => {
  const dir = fixture(t); write(dir, 'a');
  const entry = createManifest(dir, ['a']).files[0];
  for (const ending of ['\n', '\r', '\r\n']) {
    assert.throws(() => verifyManifest(dir, { version: 1, files: [{ ...entry, sha256: entry.sha256 + ending }] }));
  }
});

test('verify accepts unsorted frozen manifests and ignores unknown fields', t => {
  const dir = fixture(t); write(dir, 'a'); write(dir, 'z');
  const files = createManifest(dir, ['a', 'z']).files.reverse().map(entry => Object.freeze({ ...entry, extra: 'ignored' }));
  const manifest = Object.freeze({ version: 1, files: Object.freeze(files), extra: true });
  assert.deepEqual(verifyManifest(dir, manifest), { ok: true, unchanged: ['a', 'z'], changed: [], missing: [], unsafe: [] });
  assert.deepEqual(verifyManifest(dir, { version: 1, files: [] }), { ok: true, unchanged: [], changed: [], missing: [], unsafe: [] });
});

test('symlink roots with trailing slashes are rejected by APIs and CLI', t => {
  const dir = fixture(t); write(dir, 'a');
  const manifest = createManifest(dir, ['a']);
  const link = `${dir}-link`; fs.symlinkSync(dir, link); t.after(() => fs.rmSync(link, { force: true }));
  assert.throws(() => createManifest(`${link}/`, ['a']));
  assert.throws(() => verifyManifest(`${link}//`, manifest));
  const mf = path.join(dir, 'manifest.json'); fs.writeFileSync(mf, JSON.stringify(manifest));
  invalid(run('verify', `${link}/`, mf));
});

test('intermediate and dangling symlinks are unsafe, and missing roots throw', t => {
  const dir = fixture(t); write(dir, 'nested/a'); write(dir, 'dangling');
  const manifest = createManifest(dir, ['nested/a', 'dangling']);
  fs.rmSync(path.join(dir, 'nested'), { recursive: true });
  fs.symlinkSync(path.join(dir, 'elsewhere'), path.join(dir, 'nested'));
  fs.unlinkSync(path.join(dir, 'dangling'));
  fs.symlinkSync(path.join(dir, 'absent'), path.join(dir, 'dangling'));
  assert.deepEqual(verifyManifest(dir, manifest), { ok: false, unchanged: [], changed: [], missing: [], unsafe: ['dangling', 'nested/a'] });
  assert.throws(() => createManifest(path.join(dir, 'missing'), []));
  assert.throws(() => verifyManifest(path.join(dir, 'missing'), manifest));
});

test('verify CLI rejects excess arguments', t => {
  const dir = fixture(t); write(dir, 'a');
  const mf = path.join(dir, 'manifest.json'); fs.writeFileSync(mf, JSON.stringify(createManifest(dir, ['a'])));
  invalid(run('verify', dir, mf, 'extra'));
});

